  "nodes": {
   "opening": {
    "type": "converse",
    "task": "You asked whether you are speaking with {{title}} {{last_name}}. Beyond saying that you are Freya Bank's digital assistant and that the call is being taped, say nothing: no reason for the call, no product, amount, debt, payment or collections.\n- If the person asks a question (who is this, are you a robot, is this a scam, what is this about), answer it in one sentence without giving the reason for the call, then ask again: \"Am I speaking with {{title}} {{last_name}}?\"\n- Only \"yes\", \"that's me\", \"speaking\" or the customer's own name confirms. \"Hello\", \"go ahead\" and \"who is this\" do not.\n- If it is still unclear after your second ask, call transition_to_end_unclear.\n- If the person says twice that they do not want to talk, call transition_to_end_declined_pre.\n- If they ask for a human: ask once whether you can help; if they insist, call transfer_to_agent with queue general.\nNo other tool call in this step.",
    "enter": {
     "tts": "Hello, I am a digital assistant calling from Freya Bank. Please note that we are recording this call. Am I speaking with {{title}} {{last_name}}?"
    },
    "extract": [
     {
      "name": "who",
      "type": "string",
      "enum_values": [
       "confirmed",
       "someone_else",
       "wrong_number",
       "deceased",
       "unclear"
      ],
      "description": "Who answered, from the person's replies to 'Am I speaking with <the customer>?'. confirmed: says yes, that's me, speaking, or says the customer's own name. someone_else: says they are a different person (a relative, partner, friend, colleague) or that the customer is not there or not available. wrong_number: says this number does not belong to the customer or they do not know the customer. deceased: says the customer has died. unclear: anything else, such as hello, go ahead, who is this, or a question.",
      "min_confidence": 0.5
     }
    ],
    "tools": [
     "transfer_to_agent"
    ],
    "tool_overrides": {
     "transfer_to_agent": {
      "description": "Hand the call to a person. CALL it only when the customer insists on a human after you asked once whether you can help. Queue general.",
      "fields": {
       "queue": {
        "enum": [
         "general"
        ]
       }
      }
     }
    },
    "turns": 8,
    "overflow": "end:unclear",
    "routes": [
     {
      "to": "setup",
      "when": {
       "eq": [
        "who",
        "confirmed"
       ]
      },
      "description": "The person confirmed they are the customer"
     },
     {
      "to": "setup",
      "when": {
       "eq": [
        "who",
        "someone_else"
       ]
      },
      "description": "Someone else answered"
     },
     {
      "to": "end:wrong_number",
      "when": {
       "eq": [
        "who",
        "wrong_number"
       ]
      },
      "description": "Wrong number"
     },
     {
      "to": "end:deceased",
      "when": {
       "eq": [
        "who",
        "deceased"
       ]
      },
      "description": "The customer has died"
     },
     {
      "to": "end:transfer",
      "when": {
       "set": "transfer_queue"
      },
      "description": "The call was transferred"
     },
     {
      "to": "end:unclear",
      "tool_call": true,
      "description": "After the second ask it is still unclear whether the customer is the person on the line."
     },
     {
      "to": "end:declined_pre",
      "tool_call": true,
      "description": "The person said a second time that they do not want to talk."
     }
    ]
   },
   "setup": {
    "type": "clock",
    "next": "identity",
    "routes": [
     {
      "to": "third_party",
